// @module vendor-frontend | Vendora v1.0 | SPIT Mini Project AY 2026-27
import { useEffect, useState } from 'react';
import { Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import Loading from '../../components/common/Loading';
import { getErrorMessage, vendorAPI } from '../../services/api';
const palette=['#7C3AED','#F59E0B','#14B8A6','#3B82F6','#EC4899','#64748B'];
export default function Analytics(){const[data,setData]=useState(null);const[loading,setLoading]=useState(true);const[error,setError]=useState('');useEffect(()=>{vendorAPI.getAnalytics().then((r)=>setData(r.data.data)).catch((e)=>setError(getErrorMessage(e))).finally(()=>setLoading(false));},[]);if(loading)return<Loading label="Loading analytics…"/>;if(error)return<p className="rounded-xl bg-red-50 p-4 text-red-700">{error}</p>;const max=Math.max(1,...data.top_products_by_revenue.map((p)=>Number(p.revenue)));return <div><h1 className="page-title">Analytics</h1><p className="mt-1 text-sm text-slate-500">Revenue patterns and product performance.</p><div className="mt-6 grid gap-4 sm:grid-cols-3">{[['Conversion proxy',`${data.conversion_rate}%`],['Average order value',`₹${Number(data.avg_order_value).toLocaleString('en-IN')}`],['Return / cancel rate',`${data.return_rate}%`]].map(([l,v])=><div key={l} className="panel p-5"><p className="text-xs font-bold uppercase tracking-wider text-slate-500">{l}</p><p className="mt-2 font-mono text-3xl font-black">{v}</p></div>)}</div><div className="mt-6 grid gap-6 xl:grid-cols-2"><div className="panel p-5"><h3 className="font-bold">30-day revenue</h3><div className="mt-4 h-72"><ResponsiveContainer width="100%" height="100%"><LineChart data={data.daily_revenue}><XAxis dataKey="day" hide/><YAxis axisLine={false} tickLine={false}/><Tooltip formatter={(v)=>`₹${Number(v).toLocaleString('en-IN')}`}/><Line type="monotone" dataKey="revenue" stroke="#7C3AED" strokeWidth={3} dot={false}/></LineChart></ResponsiveContainer></div></div><div className="panel p-5"><h3 className="font-bold">Category revenue split</h3><div className="h-72"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={data.category_revenue_split} dataKey="revenue" nameKey="name" innerRadius={65} outerRadius={95} paddingAngle={4}>{data.category_revenue_split.map((_,i)=><Cell key={i} fill={palette[i%palette.length]}/>)}</Pie><Tooltip formatter={(v)=>`₹${Number(v).toLocaleString('en-IN')}`}/></PieChart></ResponsiveContainer></div></div></div><div className="panel mt-6 p-5"><h3 className="font-bold">Top products by revenue</h3><div className="mt-4 space-y-4">{data.top_products_by_revenue.length?data.top_products_by_revenue.map((p,i)=><div key={p.product_id}><div className="mb-1 flex justify-between text-sm"><span className="font-semibold">#{i+1} {p.name}</span><span className="font-mono font-bold">₹{Number(p.revenue).toLocaleString('en-IN')}</span></div><div className="h-2 rounded-full bg-slate-100"><div className="h-2 rounded-full bg-violet-600" style={{width:`${Math.max(5,(Number(p.revenue)/max)*100)}%`}}/></div></div>):<p className="text-sm text-slate-500">Delivered-order revenue will appear here.</p>}</div><p className="mt-5 text-xs text-slate-400">{data.conversion_rate_note}</p></div></div>}
